#include "ksSysExFrameTask.h"
#include <vector>
#include <tuple>
#include <iostream>
#include <stdexcept>
using T=ks::SysExFrameTask;using K=T::Kind;using S=T::Stage;using C=T::Child;using R=T::Route;using Event=std::pair<S,uint32_t>;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){try{uint64_t cases=0;auto verify=[&](K kind,unsigned state,unsigned count,unsigned command,unsigned type,unsigned size,unsigned device,unsigned bank,unsigned program,unsigned mismatch,unsigned latency){
 constexpr unsigned input=17,model=3,deviceId=7;T t(kind,uint8_t(type),0xffa31001u);unsigned storedState=state;uint16_t storedCount=uint16_t(count),storedSize=uint16_t(size);uint32_t storedCursor=0xffffffffu;unsigned reads=0,loops=0;std::vector<Event>writes;std::vector<C>children;
 while(!t.complete()&&!t.handoff()){
  check(++loops<200,"SysEx pure stalled");if(t.awaitingChild()){children.push_back(t.child());switch(t.child()){case C::Append:++storedCount;++storedCursor;check(t.resumeAppend(storedCount),"Append reply rejected");break;case C::Restart:storedState=uint8_t(storedState+1);storedCount=0;storedCursor=0x15c38;check(t.resumeChild(),"Restart rejected");break;case C::Cancel:storedState=0;check(t.resumeChild(),"Cancel rejected");break;case C::Dispatch:check(t.resumeChild(),"Dispatch rejected");break;default:throw std::runtime_error("Unexpected SysEx child");}continue;}
  auto read=[&](S s)->uint32_t{++reads;switch(s){case S::BeginReadState:case S::RestartReadState:case S::DispatchReadState:return storedState;case S::DispatchReadModel:case S::ValidateReadModelCommand:case S::PayloadReadModel:return model;case S::DispatchReadCommand:case S::ValidateReadCommand:case S::PayloadReadCommand:return command;case S::HeaderReadInput:case S::BankReadInput:case S::ModelReadInput:case S::PayloadReadInput:return input;case S::AppendReadCursor:return storedCursor;case S::AppendReadCount:return storedCount;case S::ValidateReadHeader:return 16+t.index()+(mismatch==t.index()?1:0);case S::ValidateReadModel:return 16+t.index();case S::ValidateReadDevice:return device;case S::ValidateReadDeviceId:return deviceId;case S::BankReadType:case S::LegacyReadType:case S::ModelReadType:case S::PayloadReadType:return type;case S::PayloadReadSize:return storedSize;case S::RequestReadSlot:return 19;case S::RequestReadBank:return bank;case S::RequestReadProgram:return program;default:throw std::runtime_error("Unexpected SysEx pure read");}};
  auto write=[&](S s,uint32_t d){writes.emplace_back(s,d);switch(s){case S::RestartPublishState:case S::CancelPublishState:storedState=d;break;case S::RestartPublishCount:case S::AppendPublishCount:storedCount=uint16_t(d);break;case S::RestartPublishCursor:case S::AppendPublishCursor:case S::ValidatePublishCursor:storedCursor=d;break;case S::PublishSize:storedSize=uint16_t(d);break;default:break;}};auto timing=[&](S){return latency;};const auto cost=t.nextClocks(t.publication()?latency:3);check(cost>0,"SysEx deadline stalled");const auto before=reads+writes.size();check(!t.advanceBefore(cost-1,read,write,timing)&&reads+writes.size()==before,"Early SysEx access");check(t.advanceBefore(cost,read,write,timing)==cost,"SysEx deadline differs");
 }
 std::vector<Event>ew;std::vector<C>ec;bool handed=false;R route=R::Byte;auto hand=[&](R r){handed=true;route=r;};auto cancel=[&]{ew.emplace_back(S::CancelPublishState,0);ew.emplace_back(S::CancelPublishRemaining,0);};auto request=[&]{if(type==64)hand(R::DumpPatch);else if(type==68)hand(R::DumpPerformance);else if(bank&&bank<=4&&program<100&&type==65)hand(R::DumpBank);};auto legacy=[&]{if(type==0)hand(R::LegacyPatch);else if(type==1)hand(R::LegacyPatchBank);else if(type==2)hand(R::LegacyMulti);};auto validate=[&]{if(mismatch<4)cancel();else{ew.emplace_back(S::ValidatePublishCommand,command);if((command==model||command==64||command==65)&&(device==127||device==deviceId)){ec.push_back(C::Restart);ew.emplace_back(S::ValidatePublishCursor,0x1603c);}else cancel();}};auto bankType=[&]{if(type<=2){ew.emplace_back(S::PublishSize,type<=1?128:256);ec.push_back(C::Restart);}else cancel();};auto modelType=[&]{if(type>=64)request();else if(type<=4){ew.emplace_back(S::PublishSize,type<=1||type==4?256:1024);ec.push_back(C::Restart);}else cancel();};auto payloadType=[&]{ec.push_back(C::Cancel);if(command!=model)legacy();else if(type<5){static constexpr R routes[]{R::ApplyPatch,R::WritePatchBank,R::ApplyMulti,R::WriteMultiBank,R::ApplyGlobal};hand(routes[type]);}};
 auto header=[&]{ec.push_back(C::Append);if(uint16_t(count+1)==6)validate();};auto bankData=[&]{ec.push_back(C::Append);if(uint16_t(count+1)==6)bankType();};auto modelData=[&]{ec.push_back(C::Append);if(uint16_t(count+1)==6)modelType();};auto payload=[&]{ec.push_back(C::Append);if(uint16_t(count+1)==uint16_t(size))payloadType();};
 switch(kind){case K::ByteOutput:hand(R::Byte);break;case K::CharacterOutput:hand(R::Character);break;case K::TextOutput:hand(R::Text);break;case K::NumberOutput:hand(R::Number);break;case K::Noop:break;case K::Begin:if(!state)ec.push_back(C::Restart);ec.push_back(C::Dispatch);break;case K::Restart:ew={{S::RestartPublishState,uint8_t(state+1)},{S::RestartPublishCount,0},{S::RestartPublishCursor,0x15c38}};break;case K::Dispatch:if(state==1)header();else if(state==2){if(command==model)modelData();else if(command==64||command==65)bankData();}else if(state==3)payload();break;case K::Header:header();break;case K::Append:ew={{S::AppendPublishInput,type},{S::AppendPublishCursor,0},{S::AppendPublishCount,uint16_t(count+1)}};break;case K::Validate:validate();break;case K::Cancel:cancel();break;case K::Bank:bankData();break;case K::Legacy:legacy();break;case K::Model:modelData();break;case K::Payload:payload();break;case K::Request:request();break;}
 check(writes==ew,"SysEx publication oracle differs");check(children==ec,"SysEx child ordering differs");check(t.handoff()==handed&&(!handed||t.route()==route),"SysEx action route differs");++cases;
 };
 for(unsigned latency:{0u,3u}){
  for(unsigned count=0;count<65536;++count)verify(K::Append,1,count,3,127,6,7,1,7,255,latency);
  for(unsigned type=0;type<256;++type)for(unsigned kind:{12u,13u,14u,15u,16u})for(unsigned count:{0u,5u,65535u})verify(K(kind),2,count,3,type,6,7,type,99,255,latency);
  for(unsigned device=0;device<256;++device)for(unsigned command=0;command<256;++command)verify(K::Validate,1,6,command,0,6,device,1,7,255,latency);
  for(unsigned state=0;state<256;++state)for(unsigned kind:{5u,6u,7u})for(unsigned command:{3u,64u,65u,255u})verify(K(kind),state,5,command,0,6,127,1,7,255,latency);
  for(unsigned kind=0;kind<17;++kind)for(unsigned mismatch=0;mismatch<5;++mismatch)verify(K(kind),1,5,3,0,6,7,1,7,mismatch,latency);
  for(unsigned bank=0;bank<256;++bank)for(unsigned program=0;program<256;++program)verify(K::Request,2,6,3,65,6,7,bank,program,255,latency);
 }
 std::cout<<"PASS: "<<cases<<" pure SysEx framing tasks, independent header/device/broadcast/state/block/request oracle, full16-bit append counts and byte metadata, typed child replies and early deadlines\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
